@startuml

class User {
  + FullName : string
}

class UnderAgedUser extends User {
  + StudentCard : string
}

class AdultUser extends User {
  + IDCard : string
}

class Book {
  + Title : string
  + Author : string
}

class BorrowHistory {
  + BorrowDate : date
  + ReturnDate : date
}

User "1" -- "*" BorrowHistory
BorrowHistory "*" -- "1" Book
User "0..1" -- "0..4" Book : borrows

@enduml

